),
bars AS (
  SELECT b.symbol || '0' AS Code, u.grp, CAST(b.date AS DATE) d, b.open o, b.close c, b.volume v
  FROM read_parquet('data/bars/*.parquet') b JOIN uni u ON u.sym = b.symbol
  WHERE b.open > 0
),
b2 AS (
  SELECT *, LEAD(c, 4) OVER w c5, LEAD(c, 9) OVER w c10, LEAD(c, 19) OVER w c20,
    AVG(v) OVER (PARTITION BY Code ORDER BY d ROWS BETWEEN 19 PRECEDING AND CURRENT ROW) v20
  FROM bars WINDOW w AS (PARTITION BY Code ORDER BY d)
),
fwd0 AS (SELECT Code, grp, d, v20, c, c5/o-1 r5, c10/o-1 r10, c20/o-1 r20 FROM b2 WHERE c20 IS NOT NULL),
fwd AS (
  SELECT *, r5 - AVG(r5) OVER (PARTITION BY grp, d) x5, r10 - AVG(r10) OVER (PARTITION BY grp, d) x10, r20 - AVG(r20) OVER (PARTITION BY grp, d) x20
  FROM fwd0
)
